def _end_of_local_day(day):
    start = datetime.combine(day + timedelta(days=1), time.min)
    return timezone.make_aware(start, timezone.get_current_timezone())


def prepare_coupon_rules(apps, schema_editor):
    Coupon = apps.get_model("store", "Coupon")
    Order = apps.get_model("store", "Order")
    SpinEntry = apps.get_model("store", "SpinEntry")
    SpinMilestone = apps.get_model("store", "SpinMilestone")
    SpinMilestoneAward = apps.get_model("store", "SpinMilestoneAward")
    CouponRedemption = apps.get_model("store", "CouponRedemption")
    through = Order.coupons.through

    seen = {}
    for coupon in Coupon.objects.all().order_by("id"):
        code = (coupon.code or "").strip().upper() or f"COUPON-{coupon.pk}"
        try:
            discount = int(coupon.discount)
        except (TypeError, ValueError):
            discount = 1
        discount = min(100, max(1, discount))
        keeper_id = seen.get(code)
        if keeper_id:
            for link in list(through.objects.filter(coupon_id=coupon.pk)):
                if through.objects.filter(order_id=link.order_id, coupon_id=keeper_id).exists():
                    link.delete()
                else:
                    link.coupon_id = keeper_id
                    link.save()
            coupon.delete()
            continue
        seen[code] = coupon.pk
        coupon.code = code
        coupon.discount = discount
        coupon.save(update_fields=["code", "discount"])

    for entry in SpinEntry.objects.exclude(coupon_code__isnull=True).exclude(coupon_code=""):
        code = entry.coupon_code.strip().upper()
        coupon = Coupon.objects.filter(code=code).first()
        if coupon is None:
            continue
        coupon.owner_id = entry.user_id
        coupon.usage_limit = 1
        coupon.per_customer_limit = 1
        if entry.date:
            coupon.valid_until = _end_of_local_day(entry.date)
        if entry.min_order_total is not None:
            coupon.min_subtotal = entry.min_order_total
        coupon.save()
        if entry.coupon_code != code:
            entry.coupon_code = code
            entry.save(update_fields=["coupon_code"])

    for award in SpinMilestoneAward.objects.exclude(coupon_code__isnull=True).exclude(coupon_code=""):
        code = award.coupon_code.strip().upper()
        coupon = Coupon.objects.filter(code=code).first()
        if coupon is None:
            continue
        coupon.owner_id = award.user_id
        coupon.usage_limit = 1
        coupon.per_customer_limit = 1
        milestone = SpinMilestone.objects.filter(pk=award.milestone_id).first()
        if milestone is not None and milestone.min_order_total is not None:
            coupon.min_subtotal = milestone.min_order_total
        coupon.save()
        if award.coupon_code != code:
            award.coupon_code = code
            award.save(update_fields=["coupon_code"])

    paid = Order.objects.filter(payment_status__in=["paid", "cash_on_delivery"])
    for order in paid:
        link = through.objects.filter(order_id=order.pk).order_by("coupon_id").first()
        if link is None or CouponRedemption.objects.filter(order_id=order.pk).exists():
            continue
        CouponRedemption.objects.create(
            order_id=order.pk,
            coupon_id=link.coupon_id,
            user_id=order.customer_id,
        )


